import{_ as a,o as l,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Performance Meeting 2023--01-19","description":"","frontmatter":{"title":"Ceph Performance Meeting 2023--01-19","date":"2023-01-20T00:00:00.000Z","updated":"2023-01-20T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","RBD","写放大"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Performance_Meeting_2023--01-19.md","filePath":"posts/2023/Ceph_Performance_Meeting_2023--01-19.md","lastUpdated":1780459816000}'),i={name:"posts/2023/Ceph_Performance_Meeting_2023--01-19.md"};function o(n,e,s,h,d,u){return l(),t("div",null,[...e[0]||(e[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节与讨论主题" tabindex="-1">关键细节与讨论主题 <a class="header-anchor" href="#关键细节与讨论主题" aria-label="Permalink to &quot;关键细节与讨论主题&quot;">​</a></h4><ol><li><p><strong>构建问题修复</strong>：</p><ul><li>会议开始时，提到了一个长期存在的构建问题已修复，该问题与Luster系统相关。</li></ul></li><li><p><strong>Pull Requests (PRs) 讨论</strong>：</p><ul><li><strong>有界迭代器 (Bounded Iterators)</strong>：Igor提出了一个关于ARM范围键的有界迭代器的PR，该PR旨在解决RocksDB性能下降问题，特别是与map clear函数和多个列族的迭代有关。</li><li><strong>Arrow Flight功能</strong>：讨论了添加Arrow Flight功能的初始提交，这是一个RPC框架，用于低延迟数据传输。</li><li><strong>硬件文档重写</strong>：一个关于重写硬件文档的旧PR被关闭，可能已被新文档取代。</li></ul></li><li><p><strong>性能与优化讨论</strong>：</p><ul><li><strong>RBD镜像快照性能</strong>：Adam的工作显著提高了RBD镜像和快照的速度。</li><li><strong>写放大问题</strong>：Josh提到了在从Nautilus升级到Pacific时观察到的写放大问题，特别是在RBD方面。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>对于有界迭代器的PR，决定继续测试并可能进行后向移植。</li><li>对于Arrow Flight功能的PR，决定继续实验并寻找更好的实现模型。</li><li>对于硬件文档重写的PR，决定关闭，因为可能已被新文档取代。</li><li>对于写放大问题，Josh计划在staging环境中进行更多测试。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续测试和优化有界迭代器的PR，确保其性能和稳定性。</li><li>进一步实验Arrow Flight功能，探索其在RGW和OSD集成中的潜力。</li><li>调查和解决写放大问题，特别是通过分析RBD和RGW的性能数据，以及可能的配置调整。</li><li>继续监控和优化RBD镜像和快照的性能，确保Adam的工作在生产环境中稳定运行。</li></ul><h4 id="其他备注" tabindex="-1">其他备注 <a class="header-anchor" href="#其他备注" aria-label="Permalink to &quot;其他备注&quot;">​</a></h4><ul><li>会议超时，决定将未讨论完的话题推迟到下一次会议。</li></ul><h4 id="参会人员" tabindex="-1">参会人员 <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员&quot;">​</a></h4><ul><li>会议由Josh主持，Igor、Adam、Corey等参与讨论。</li></ul><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h4><p>会议涵盖了多个技术议题，包括构建问题的解决、新功能的讨论和性能问题的深入分析。团队将继续在这些领域进行工作，以确保Ceph系统的稳定性和性能优化。</p>',13)])])}const _=a(i,[["render",o]]);export{p as __pageData,_ as default};
